y=dv_dt
def fit(f,n,tries=40,seed=0):
    best=None
    rng=np.random.default_rng(seed)
    for i in range(tries):
        p0=rng.normal(0,1.2,n)
        try:
            r=least_squares(lambda p:np.nan_to_num(f(p)-y,nan=1e3,posinf=1e3,neginf=-1e3),p0)
        except Exception as e: continue
        if best is None or r.cost<best.cost: best=r
    return best.cost*2/len(y)/np.var(y),np.round(best.x,4)
